class Solution {
public:
    long long countSubstrings(string s) {
        vector<vector<long long>> cnt(10);
        for (int d = 1; d <= 9; d++) cnt[d].assign(d, 0);
        long long ans = 0;
        for (char ch : s) {
            int c = ch - '0';
            vector<vector<long long>> nw(10);
            for (int d = 1; d <= 9; d++) nw[d].assign(d, 0);
            for (int d = 1; d <= 9; d++) {
                for (int r = 0; r < d; r++) {
                    long long v = cnt[d][r];
                    if (v) nw[d][(r * 10 + c) % d] += v;
                }
                nw[d][c % d] += 1;
                if (c != 0 && c == d) ans += nw[d][0];
            }
            cnt = move(nw);
        }
        return ans;
    }
};

