class Solution {
    public long countSubstrings(String s) {
        long[][] cnt = new long[10][];
        for (int d = 1; d <= 9; d++) cnt[d] = new long[d];
        long ans = 0;
        for (char ch : s.toCharArray()) {
            int c = ch - '0';
            long[][] nw = new long[10][];
            for (int d = 1; d <= 9; d++) nw[d] = new long[d];
            for (int d = 1; d <= 9; d++) {
                for (int r = 0; r < d; r++) {
                    long v = cnt[d][r];
                    if (v != 0) nw[d][(r * 10 + c) % d] += v;
                }
                nw[d][c % d] += 1;
                if (c != 0 && c == d) ans += nw[d][0];
            }
            cnt = nw;
        }
        return ans;
    }
}

