var countSubstrings = function(s) {
    const cnt = Array.from({length: 10}, (_, d) => new Array(d).fill(0));
    let ans = 0;
    for (const ch of s) {
        const c = ch.charCodeAt(0) - 48;
        const nw = Array.from({length: 10}, (_, d) => new Array(d).fill(0));
        for (let d = 1; d <= 9; d++) {
            for (let r = 0; r < d; r++) {
                const v = cnt[d][r];
                if (v) nw[d][(r * 10 + c) % d] += v;
            }
            nw[d][c % d] += 1;
            if (c !== 0 && c === d) ans += nw[d][0];
        }
        for (let d = 1; d <= 9; d++) cnt[d] = nw[d];
    }
    return ans;
};
